class Solution {
public:
 bool possibleToStamp(vector<vector<int>>& grid,int stampHeight,int stampWidth){
  int m=grid.size(),n=grid[0].size();
  vector<vector<int>> pref(m+1,vector<int>(n+1)),diff(m+1,vector<int>(n+1));
  for(int i=0;i<m;++i)for(int j=0;j<n;++j)
   pref[i+1][j+1]=grid[i][j]+pref[i][j+1]+pref[i+1][j]-pref[i][j];
  for(int i=0;i+stampHeight<=m;++i)for(int j=0;j+stampWidth<=n;++j){
   int r=i+stampHeight,c=j+stampWidth;
   if(pref[r][c]-pref[i][c]-pref[r][j]+pref[i][j])continue;
   ++diff[i][j];--diff[r][j];--diff[i][c];++diff[r][c];
  }
  for(int i=0;i<m;++i)for(int j=0;j<n;++j){
   int up=i?diff[i-1][j]:0,left=j?diff[i][j-1]:0,diag=i&&j?diff[i-1][j-1]:0;
   diff[i][j]+=up+left-diag;
   if(grid[i][j]==0 && diff[i][j]==0)return false;
  }
  return true;
 }
};
